import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        long k = nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        final long NEG = -(1L << 62);
        long answer = NEG;
        for (int divide = 0; divide < 2; divide++) {
            // before: modification not started; inside: in the modified range; after: range closed.
            long before = NEG, inside = NEG, after = NEG;
            for (long v : a) {
                long changed = divide == 1 ? v / k : v * k; // Java division truncates toward zero
                long newAfter = Math.max(inside + v, after + v);
                long newInside = Math.max(changed, Math.max(before + changed, inside + changed));
                before = Math.max(v, before + v);
                inside = newInside;
                after = newAfter;
                answer = Math.max(answer, Math.max(inside, after));
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n, k := int(nextInt()), nextInt()
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	const neg = -(int64(1) << 62)
	answer := neg
	for divide := 0; divide < 2; divide++ {
		// before: modification not started; inside: in the modified range; after: range closed.
		before, inside, after := neg, neg, neg
		for _, v := range a {
			changed := v * k
			if divide == 1 {
				changed = v / k // Go division truncates toward zero
			}
			after, inside, before = max(inside+v, after+v), max(changed, before+changed, inside+changed), max(v, before+v)
			answer = max(answer, inside, after)
		}
	}
	fmt.Println(answer)
}
